    p = ((int32_t)((5.33740603e-02) * 16777216.0 + ((5.33740603e-02) < 0 ? -0.5 : 0.5))) + qm(p, x2);
    p = ((int32_t)((1.333923995e-01) * 16777216.0 + ((1.333923995e-01) < 0 ? -0.5 : 0.5))) + qm(p, x2);
    p = ((int32_t)((3.333314036e-01) * 16777216.0 + ((3.333314036e-01) < 0 ? -0.5 : 0.5))) + qm(p, x2);
