    p = ((int32_t)((-0.0161657367) * 16777216.0 + ((-0.0161657367) < 0 ? -0.5 : 0.5))) + qm(p, t2);
    p = ((int32_t)((0.0429096138) * 16777216.0 + ((0.0429096138) < 0 ? -0.5 : 0.5))) + qm(p, t2);
    p = ((int32_t)((-0.0752896400) * 16777216.0 + ((-0.0752896400) < 0 ? -0.5 : 0.5))) + qm(p, t2);
    p = ((int32_t)((0.1065626393) * 16777216.0 + ((0.1065626393) < 0 ? -0.5 : 0.5))) + qm(p, t2);
    p = ((int32_t)((-0.1420889944) * 16777216.0 + ((-0.1420889944) < 0 ? -0.5 : 0.5))) + qm(p, t2);
    p = ((int32_t)((0.1999355085) * 16777216.0 + ((0.1999355085) < 0 ? -0.5 : 0.5))) + qm(p, t2);
    p = ((int32_t)((-0.3333314528) * 16777216.0 + ((-0.3333314528) < 0 ? -0.5 : 0.5))) + qm(p, t2);
