    int64_t d = (int64_t)(1 << 24) + qm(r, g) + qm(g, g);
    f->h = d <= INT32_MAX ? (int32_t)((1LL << 48) / (int32_t)d) : (int32_t)((1LL << 44) / (int32_t)(d >> 4));
