static const uint32_t METAL_INC[6] = {((uint32_t)((205.3) * 97391.548)), ((uint32_t)((304.4) * 97391.548)), ((uint32_t)((369.6) * 97391.548)), ((uint32_t)((522.7) * 97391.548)), ((uint32_t)((540.0) * 97391.548)), ((uint32_t)((800.0) * 97391.548))};
