    if (o->ph >= (1 << 24)) {
        o->ph -= (1 << 24);
        t = qdiv(o->ph, o->f);
        th -= qm(t, t) / 2;
        t = (1 << 24) - t;
        o->next += qm(t, t) / 2;
    }
