static void clap_start(dvoice_t *v, uint32_t burst, uint32_t nb, uint32_t jitter)
{
    v->inc[2] = burst;
    v->x[0] = (int32_t)nb;
    v->x[1] = (int32_t)jitter;
    v->env[0] = v->env[1] = (1 << 24);
    v->k[0] = dk(26); /* the last burst: ~20 ms */
    clap_next_burst(v, burst);
}
