    v->inc[0] = inc_tune(((uint32_t)((1667) * 97391.548)), dm_tune(t));
    v->inc[1] = inc_tune(((uint32_t)((455) * 97391.548)), dm_tune(t));
    v->env[0] = (1 << 24);
    v->k[0] = dk(13 + p[1] * 20 / 127);
    v->x[0] = 32767 - p[2] * 150;
    v->x[1] = 8000 + p[2] * 150;
    v->x[2] = p[3];
    dsvf_coef(&v->c[0], 15511, 0);
