    if (x <= 0)
        return 0;
    if (x >= 127)
        return 65536u;
    d16 = (int32_t)(((int64_t)(xt_log2((uint32_t)x) - xt_log2(127u)) * p8 * 192) >> 24); /* 1/192 octave */
    return pow2_q16(d16 < -3072 ? -3072 : d16);
