        uint32_t fr = (uint32_t)(((uint64_t)(uint32_t)((int32_t)((692.0 / 44100.0) * 16777216.0 + ((692.0 / 44100.0) < 0 ? -0.5 : 0.5))) * pow2_q16((rt * 384 + 50) / 100)) >> 16);
        tn_bq_set(&c->rq, 0, (int32_t)fr, 34493);
        c->re = (uint32_t)(((uint64_t)tn_db(tn_tab(TN_K5, RL, 5, ro)) * 536553u)); /* rl x 2.8 / L, Q30 */
        c->rd = (0xFFFFFFFFu / rtau16) << 4;
