        for (i = b + 1u; i < PKV(55)[k].n; i++) /* (low to high: a chord's few, by insertion) */
            for (j = i; j > b && PKV(55)[k].note[j - 1u] > PKV(55)[k].note[j]; j--) {
                uint8_t x = PKV(55)[k].note[j], y = PKV(55)[k].vel[j];
                PKV(55)[k].note[j] = PKV(55)[k].note[j - 1u];
                PKV(55)[k].vel[j] = PKV(55)[k].vel[j - 1u];
                PKV(55)[k].note[j - 1u] = x;
                PKV(55)[k].vel[j - 1u] = y;
            }
