    for (j = 0; j < PKV(55)[k].n;)
        if (PKV(55)[k].note[j] == note) {
            if (j >= PKV(55)[k].n - PKV(55)[k].fresh)
                PKV(55)[k].fresh--;
            sq_take(k, j);
        } else
            j++;
