/* m samples of one step (no boundary inside). sd: (1.3) SPREAD's side signal (fx.c mix_spread) or 0: it gets the gate
 * and the live sound's share of the cross-fade (the repeat is the mono recording: on PAN); sd2 ((2.0, #36) the lane
 * pans' second side sum) or 0 the same. Inlined into both callers: slicer_track's (sd, sd2 0) is the code it always was */
static inline void sl_seg(const track_t *t, sl_t *s, int16_t *buf, int32_t *b,
                                                          int32_t *sd, int32_t *sd2, uint32_t m)
{
    uint32_t mode = (uint32_t)t->p[P_SLCR], j, nbit = (sl_pattern(t) >> ((s->idx + 1u) & 15u)) & 1u;
    int32_t depth = t->p[P_SLDEPTH] * 258; /* Q15, 0..32766 */
    int32_t tc = mode == SL_GATE && !s->bit ? depth : 0; /* gate closure of this step */
    int32_t tn = mode == SL_GATE && !nbit ? depth : 0; /* .. of the next one */
    int32_t tw = mode == SL_STUT && s->loop ? depth : 0; /* repeat level */
    for (j = 0; j < m; j++) {
        int32_t x = b[j], y, tg = tc;
        uint32_t left = s->len - s->pos - j; /* samples to the step end, >= 1 */
        if (left <= (uint32_t)(1 << 7) && tn > tg)
            tg = tn; /* close by the boundary */
        s->gc += clamp(tg - s->gc, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        s->w += clamp(tw - s->w, -(32768 / (1 << 7)), (32768 / (1 << 7)));
        y = s->gc ? x - mulq16(x, (uint32_t)s->gc << 1) : x;
        if (sd) {
            int32_t z = sd[j];
            if (s->gc)
                z -= mulq16(z, (uint32_t)s->gc << 1);
            if (s->w)
                z -= mulq16(z, (uint32_t)s->w << 1);
            sd[j] = z;
        }
        if (sd2) {
            int32_t z = sd2[j];
            if (s->gc)
                z -= mulq16(z, (uint32_t)s->gc << 1);
            if (s->w)
                z -= mulq16(z, (uint32_t)s->w << 1);
            sd2[j] = z;
        }
        if (s->rec_on) { /* 2:1, the pair's mean; Q15 >> 2 (the mix's headroom) */
            if ((s->pos + j) & 1u) {
                buf[s->rec] = (int16_t)clamp((s->half + x) >> 3, -32768, 32767);
                if (++s->rec >= 4096u)
                    s->rec_on = 0;
            } else {
                s->half = x;
            }
        }
        if (s->loop) { /* the repeat, windowed, read between samples */
            uint32_t rp = s->rp, e = s->loop - 1u - rp;
            int32_t r = buf[rp >> 1];
            if (rp & 1u)
                r = (r + buf[((rp >> 1) + 1u) & (4096u - 1u)]) >> 1;
            r <<= 2;
            if (rp < e)
                e = rp;
            if (left - 1u < e)
                e = left - 1u;
            if (e < (uint32_t)(1 << 7))
                r = (r * (int32_t)e) >> 7;
            if (++s->rp >= s->loop)
                s->rp = 0;
            y += mulq16(r - y, (uint32_t)s->w << 1);
        } else if (s->w) {
            y -= mulq16(y, (uint32_t)s->w << 1); /* (the repeat ended on a boundary: it is 0 there) */
        }
        b[j] = y;
    }
}
/* the step clock over n samples and the SLICER on b (0: the clock only, the track is silent) */
static void slicer_track(const track_t *t, int32_t *b, uint32_t n)
{
    uint32_t k = (uint32_t)(t - PKV(2)), i = 0;
    sl_t *s = &PKV(62)[k];
    int act = b && (t->p[P_SLCR] != SL_OFF || s->gc || s->w);
    while (i < n) {
        uint32_t m;
        if (s->pos >= s->len)
            sl_enter(t, s);
        m = s->len - s->pos;
        if (m > n - i)
            m = n - i;
        if (act)
            sl_seg(t, s, PKV(61)[k], b + i, 0, 0, m);
        s->pos += m;
        i += m;
    }
}
/* (1.3) slicer_track with SPREAD's side signal sd (fx.c mix_spread; b != 0); ((2.0, #36) the lane pans' second sum,
 * sd2, or 0) */
static void slicer_track_sd(const track_t *t, int32_t *b, int32_t *sd, int32_t *sd2, uint32_t n)
{
    uint32_t k = (uint32_t)(t - PKV(2)), i = 0;
    sl_t *s = &PKV(62)[k];
    int act = t->p[P_SLCR] != SL_OFF || s->gc || s->w;
    while (i < n) {
        uint32_t m;
        if (s->pos >= s->len)
            sl_enter(t, s);
        m = s->len - s->pos;
        if (m > n - i)
            m = n - i;
        if (act)
            sl_seg(t, s, PKV(61)[k], b + i, sd + i, sd2 ? sd2 + i : 0, m);
        s->pos += m;
        i += m;
    }
}
/* a silent part must still be rendered: a repeat is playing or fading (fx.c mix_part) */
static int slicer_busy(const track_t *t)
{
    const sl_t *s = &PKV(62)[t - PKV(2)];
    return s->w || (t->p[P_SLCR] == SL_STUT && s->loop);
}
