static inline int32_t lowcut1(int32_t x, int32_t *lc, int32_t *err, uint32_t sh) /* x minus its one-pole low-pass */
{
    int32_t e = x - *lc + *err, d = e >> sh;
    *err = e - (d << sh);
    *lc += d;
    return x - *lc;
}
