            a->len = (uint8_t)(i ? i : 1u);
        a->st[i] = (uint8_t)(st == AS_END ? AS_ON : st);
        a->tr[i] = (int8_t)clamp((int32_t)((b[i] & 63u) ^ 32u) - 32, -24, 24);
