    if (rec_on(t))
        return; /* (REC records it itself) */
    step = take_stamp(t, &pass, &feel);
    i = PKV(177) % 256u;
    if (PKV(177) >= 256u && PKV(175)[i].pass + 1u > PKV(180)[PKV(175)[i].trk % 6])
        PKV(180)[PKV(175)[i].trk % 6] = (uint16_t)(PKV(175)[i].pass + 1u); /* (that pass: a partial take) */
    PKV(175)[i].pass = (uint16_t)pass;
    PKV(175)[i].trk = (uint8_t)trk_index(t);
    PKV(175)[i].step = (uint8_t)step;
    PKV(175)[i].note = (uint8_t)note;
    PKV(175)[i].vel = (uint8_t)vel;
    PKV(175)[i].feel = (int8_t)feel;
    __asm__ volatile("" ::: "memory");
    PKV(177)++;
