static int step_cond_ok(const track_t *t, const step_t *s, uint32_t ahead)
{
    static const uint8_t A[TC_PRE] = {0, 0, 0, 1, 2, 1, 2, 3, 1, 2, 3, 4};
    static const uint8_t B[TC_PRE] = {1, 1, 1, 2, 2, 3, 3, 3, 4, 4, 4, 4};
    uint32_t c = s->cond, p = PKV(179)[trk_index(t)] + ahead, k = trk_index(t);
    int ok;
    if (c == TC_NONE || c >= TC_COUNT)
        return 1;
    if (c == TC_PRE || c == TC_NPRE) /* (custom) the last one's result (not changed by this) */
        return (c == TC_PRE) == (PKV(187)[k] != 0u);
    if (c == TC_NEI || c == TC_NNEI) /* (custom) the track before's last one (it ticks first) */
        ok = (c == TC_NEI) == (k > 0u && k < 6 && PKV(187)[k - 1u] != 0u);
    else
    if (c == TC_1ST || c == TC_N1ST)
        ok = (c == TC_1ST) == (p == 1u);
    else if (c == TC_FILL || c == TC_NFILL)
        ok = (c == TC_FILL) == (PKV(186) != 0u);
    else
        ok = p > 0u && (p - 1u) % B[c] + 1u == A[c];
    PKV(187)[k] = (uint8_t)ok;
    return ok;
}
