        int32_t r = t->p[P_RTVEL], j = (int32_t)(hits - 1u - (skip & (1u << 16) ? t->rat_left : hits - 1u));
        int32_t x = r > 0 ? (int32_t)hits - 1 - j : j, a = r < 0 ? -r : r; /* (x: parts from the full one) */
        int32_t g = 128 - a * 2 * x / ((int32_t)hits - 1); /* Q7: 1 .. 1 - |r| / 64 */
