        PKV(139) = PKV(138);
        memset(PKV(229), 0, sizeof PKV(229));
        memset(PKV(228), 0, sizeof PKV(228));
        memset(PKV(230), 0, sizeof PKV(230));
        memset(PKV(167), 0, sizeof PKV(167));
        PKV(163) = 0;
        for (i = 0; i < 6; i++) {
            PKV(2)[i].rh_n = PKV(2)[i].rskip_n = 0;
            PKV(2)[i].seq_n = PKV(2)[i].seq_hold = PKV(2)[i].slide_glide = PKV(2)[i].rat_left = 0;
        }
        pr |= (1u << 6) - 1u;
